11	/**
12	 * MenuScene — title, Play (→ Game), and a persisted mute toggle. Fires no
13	 * analytics (start_game fires when the run actually begins, in GameScene).
14	 */
15	export class MenuScene extends Phaser.Scene {
16	  constructor() {
17	    super({ key: SceneKey.Menu });
18	  }
19	
20	  create(): void {
21	    const cx = GAME_WIDTH / 2;
22	
23	    // Drive the browser tab title from i18n (single localized source for the
24	    // game name). The on-canvas title is the `ui_title_logo` asset — we do NOT
25	    // draw `menu_title` over the logo (that would overlap the placeholder).
26	    document.title = t('menu_title');
27	
28	    this.add.image(cx, GAME_HEIGHT / 2, KEYS.screen_bg_menu);
29	    this.add.image(cx, 180, KEYS.ui_title_logo);
30	
31	    this.add
32	      .text(cx, 330, t('menu_subtitle'), {
33	        fontFamily: 'system-ui, sans-serif',
34	        fontSize: '24px',
35	        color: '#3a444d',
36	      })
37	      .setOrigin(0.5);
38	
39	    createButton(this, {
40	      x: cx,
41	      y: 450,
42	      texture: KEYS.ui_btn_play,
43	      label: t('menu_play'),
44	      onClick: () => {
45	        playSfx(this, Sfx.ui);
46	        this.scene.start(SceneKey.Game);
47	      },
48	    });
49	
50	    this.add
51	      .text(cx, 550, t('menu_hint'), {
52	        fontFamily: 'system-ui, sans-serif',
53	        fontSize: '20px',
54	        color: '#3a444d',
55	      })
56	      .setOrigin(0.5);
57	
58	    // Promo teaser chip — the same code the results CTA rewards (spec §6.4) (tap-to-copy).
59	    this.buildPromoCopyChip(cx, 648);
60	
61	    this.buildMuteToggle();
62	
63	    // Menu loop music. Honors the persisted mute (global sound.mute) and the iOS
64	    // unlock installed in BootScene; on first load it plays once the user taps.
65	    playMusic(this, Music.menu);
66	  }
67	
68	  private buildMuteToggle(): void {
69	    const muteBtn = this.add.image(GAME_WIDTH - 52, 52, this.muteTexture());
70	    enlargeHitArea(muteBtn); // full-icon + comfortable tap target (§10.4)
71	
72	    const label = this.add
73	      .text(GAME_WIDTH - 52, 90, this.muteLabel(), {
74	        fontFamily: 'system-ui, sans-serif',
75	        fontSize: '14px',
76	        color: '#9fb0bd',
77	      })
78	      .setOrigin(0.5, 0);
79	
80	    muteBtn.on(Phaser.Input.Events.POINTER_UP, () => {
81	      AudioManager.toggle(this.sound);
