133	    const label = this.add
134	      .text(cx, 705, t('results_promo_copied'), {
135	        fontFamily: 'system-ui, sans-serif',
136	        fontSize: '14px',
137	        fontStyle: 'bold',
138	        color: '#6cc04a',
139	      })
140	      .setOrigin(0.5)
141	      .setAlpha(1);
142	    this.tweens.add({
143	      targets: label,
144	      alpha: 0,
145	      duration: PROMO_COPY_FADE_MS,
146	      ease: 'Quad.in',
147	      onComplete: () => label.destroy(),
148	    });
149	  }
150	}
